import math

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

# Test small coefficients A, B, C, and small x
# Range for coefficients: [-1, 1]
# Range for x: [-3, 3]

A_range = [-1, 0, 1]
B_range = [-1, 0, 1]
C_range = [-1, 0, 1]
X_range = range(-3, 4)

print("--- Testing P(x) = x^3 + Ax^2 + Bx + C ---")

found_cases = []

for A in A_range:
    for B in B_range:
        for C in C_range:
            P_func = lambda x: x**3 + A*x**2 + B*x + C

            squares_found = []
            for x in X_range:
                p_x = P_func(x)
                if is_square(p_x):
                    squares_found.append((x, p_x))

            if squares_found:
                found_cases.append({
                    'A': A, 'B': B, 'C': C, 
                    'squares': squares_found
                })
                print(f"P(x) = x^3 + {A}x^2 + {B}x + {C} found squares at x values: {[x for x, p_x in squares_found]}")

print("\nSummary of found polynomial candidates:")
for case in found_cases:
    print(f"A={case['A']}, B={case['B']}, C={case['C']}: {case['squares']}")
